const MAX=20*1024*1024,AGE=7*86400000,PREFIX='/api/tutor/';
const enc=new TextEncoder();
const fail=(status,message)=>{throw Object.assign(new Error(message),{status})};
const json=(data,status=200,extra={})=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store','X-Content-Type-Options':'nosniff',...extra}});
const token=()=>[...crypto.getRandomValues(new Uint8Array(32))].map(x=>x.toString(16).padStart(2,'0')).join('');
const hash=async s=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(s)))].map(x=>x.toString(16).padStart(2,'0')).join('');
function equal(a,b){if(typeof a!=='string'||typeof b!=='string'||a.length!==b.length)return false;let v=0;for(let i=0;i<a.length;i++)v|=a.charCodeAt(i)^b.charCodeAt(i);return v===0}
async function password(value,salt=token()){const k=await crypto.subtle.importKey('raw',enc.encode(value),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:enc.encode(salt),iterations:100000},k,256);return salt+':'+[...new Uint8Array(bits)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function verify(value,stored){return equal(await password(value,stored.split(':')[0]),stored)}
function text(v,max,required=false){if(typeof v!=='string'||v.length>max||(required&&!v.trim()))fail(400,'Check the required fields and text lengths.');return v.trim()}
function credentials(b){const email=text(b.email,254,true).toLowerCase(),pass=text(b.password,256,true);if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||pass.length<12)fail(400,'Use an email address and a password of at least 12 characters.');return {email,pass}}
async function bounded(req,limit){const reader=req.body?.getReader();if(!reader)return new Uint8Array();const chunks=[];let n=0;while(true){const {done,value}=await reader.read();if(done)break;n+=value.length;if(n>limit){await reader.cancel();fail(413,'File too large. Use a shorter recording, at most 20 MB.')}chunks.push(value)}const bytes=new Uint8Array(n);let pos=0;for(const c of chunks){bytes.set(c,pos);pos+=c.length}return bytes}
async function body(req){try{return JSON.parse(new TextDecoder().decode(await bounded(req,24000)))}catch(e){if(e.status)throw e;fail(400,'Invalid request.')}}
function stmt(env,sql,...args){return env.DB.prepare(sql).bind(...args)}
async function first(env,sql,...args){return stmt(env,sql,...args).first()}
async function all(env,sql,...args){return (await stmt(env,sql,...args).all()).results}
async function auth(req,env){const raw=req.headers.get('Cookie')?.match(/(?:^|;\s*)__Host-saxworx=([a-f0-9]{64})(?:;|$)/)?.[1];if(!raw)fail(401,'Please sign in.');const u=await first(env,'SELECT u.id,u.email,u.name,u.role,u.owner,u.created FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND s.expires>?',await hash(raw),Date.now());if(!u)fail(401,'Your session expired. Please sign in again.');return u}
async function session(env,u){const raw=token();await stmt(env,'INSERT INTO sessions VALUES(?,?,?)',await hash(raw),u.id,Date.now()+AGE).run();return json({user:{id:u.id,name:u.name,email:u.email,role:u.role,owner:u.owner}},200,{'Set-Cookie':`__Host-saxworx=${raw}; Path=/; Secure; HttpOnly; SameSite=Strict; Max-Age=604800`})}
async function limit(env,key){const now=Date.now(),id=await hash(key);await stmt(env,'INSERT INTO auth_limits VALUES(?,1,?) ON CONFLICT(key) DO UPDATE SET count=CASE WHEN expires<? THEN 1 ELSE count+1 END,expires=CASE WHEN expires<? THEN excluded.expires ELSE expires END',id,now+900000,now,now).run();const a=await first(env,'SELECT count FROM auth_limits WHERE key=?',id);if(a.count>10)fail(429,'Too many attempts. Wait 15 minutes and try again.')}
function tutor(u){if(u.role!=='tutor')fail(403,'Tutor access required.')}
async function ownMedia(env,u,id,kind){if(!id)return null;const m=await first(env,'SELECT * FROM media WHERE id=? AND owner_id=?',id,u.id);if(!m||!(kind==='sheet'?m.type==='application/pdf':/^(audio|video)\//.test(m.type)))fail(400,'Select your own valid uploaded file.');return m.id}
async function assignment(env,u,id){const a=await first(env,'SELECT * FROM assignments WHERE id=? AND (tutor_id=? OR student_id=?)',id,u.id,u.id);if(!a)fail(404,'Assignment not found.');return a}
async function listData(env,u){const assignments=await all(env,'SELECT a.*,t.name tutor_name,s.name student_name FROM assignments a JOIN users t ON t.id=a.tutor_id JOIN users s ON s.id=a.student_id WHERE a.tutor_id=? OR a.student_id=? ORDER BY a.created DESC LIMIT 200',u.id,u.id);const submissions=await all(env,'SELECT s.* FROM submissions s JOIN assignments a ON a.id=s.assignment_id WHERE a.tutor_id=? OR a.student_id=? ORDER BY s.created DESC LIMIT 500',u.id,u.id);const reviews=await all(env,'SELECT r.* FROM reviews r JOIN submissions s ON s.id=r.submission_id JOIN assignments a ON a.id=s.assignment_id WHERE a.tutor_id=? OR a.student_id=? ORDER BY r.created DESC LIMIT 500',u.id,u.id);const students=u.role==='tutor'?await all(env,'SELECT u.id,u.name,u.email FROM students s JOIN users u ON u.id=s.student_id WHERE s.tutor_id=? ORDER BY u.name',u.id):[];const media=await all(env,`SELECT m.id,m.name,m.type,m.size FROM media m WHERE EXISTS(SELECT 1 FROM assignments a WHERE (a.tutor_id=? OR a.student_id=?) AND (a.demo_id=m.id OR a.sheet_id=m.id)) OR EXISTS(SELECT 1 FROM submissions s JOIN assignments a ON a.id=s.assignment_id WHERE (a.tutor_id=? OR a.student_id=?) AND s.media_id=m.id) OR EXISTS(SELECT 1 FROM reviews r JOIN submissions s ON s.id=r.submission_id JOIN assignments a ON a.id=s.assignment_id WHERE (a.tutor_id=? OR a.student_id=?) AND r.media_id=m.id)`,u.id,u.id,u.id,u.id,u.id,u.id);return {assignments,submissions,reviews,students,media}}
