 if(path==='register'&&method==='POST'){const b=await body(req),{email,pass}=credentials(b);await limit(env,'register:'+req.headers.get('CF-Connecting-IP'));if(!env.TURNSTILE_SECRET_KEY)fail(503,'Public registration is not connected yet.');const result=await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify',{method:'POST',body:new URLSearchParams({secret:env.TURNSTILE_SECRET_KEY,response:b.challenge||''})});const check=await result.json();if(!check.success||check.hostname!==new URL(req.url).hostname)fail(400,'Complete the security check again.');const u={id:crypto.randomUUID(),email,name:text(b.name,100,true),role:'student',owner:0};try{await stmt(env,'INSERT INTO users VALUES(?,?,?,?,?,?,?)',u.id,email,u.name,u.role,await password(pass),0,Date.now()).run()}catch{fail(409,'Email already registered. Sign in.')}return session(env,u)}
