 if(['login','owner-login'].includes(path)&&method==='POST'){const b=await body(req),{email,pass}=credentials(b);await limit(env,'login:'+email);const u=await first(env,'SELECT * FROM users WHERE email=?',email);const dummy='0'.repeat(64)+':'+'0'.repeat(64);const good=await verify(pass,u?.password||dummy);if(!u||!good||(path==='owner-login'&&!u.owner))fail(401,'Email or password is incorrect.');return session(env,u)}
