  const instrument={Saxophone:'sax',Piano:'piano',Guitar:'guitar'}[input.instrument_type];
  if(!instrument)fail(400,'Choose Saxophone, Piano or Guitar.');
  if(!(await instrumentAccess(env,u))[instrument].unlocked)fail(402,'Subscribe to unlock this instrument.');
    await limit(env,'music-tutor:'+u.id);
  if(!env.MUSIC_TUTOR_PROXY_TOKEN)fail(503,'Tutor service is not configured.');
  const serviceUrl=env.MUSIC_TUTOR_API_URL||'http://127.0.0.1:8000/api/v1/tutor/feedback';
  const upstream=await fetch(serviceUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/octet-stream','Authorization':'Bearer '+env.MUSIC_TUTOR_PROXY_TOKEN},body:requestBytes});
  const headers=new Headers({'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'});
  for(const name of ['Content-Type','X-Audio-Format']){const value=upstream.headers.get(name);if(value)headers.set(name,value)}
