 if(path==='invite'&&method==='POST'){tutor(u);const b=await body(req),role=b.role==='tutor'?'tutor':'student';if(role==='tutor'&&!u.owner)fail(403,'Only the app owner can invite tutors.');const raw=token();await stmt(env,'INSERT INTO invites VALUES(?,?,?,?,NULL)',await hash(raw),u.id,Date.now()+AGE,role).run();return json({link:new URL(req.url).origin+'/#join='+raw,expiresDays:7,role})}
 if(path==='upload'&&method==='POST'){if(!req.headers.get('Content-Type')?.toLowerCase().startsWith('multipart/form-data'))fail(400,'Use the file upload form.');const count=await first(env,'SELECT count(*) n FROM media WHERE owner_id=?',u.id);if(count.n>=100)fail(413,'Upload limit reached. Ask the app owner to archive old recordings.');const bytes=await bounded(req,MAX+65536),form=await new Request(req.url,{method:'POST',headers:{'Content-Type':req.headers.get('Content-Type')||''},body:bytes}).formData(),file=form.get('file');if(!file||typeof file.arrayBuffer!=='function'||file.size<1||file.size>MAX)fail(400,'Choose an audio/video file or PDF, at most 20 MB.');const type=file.type.split(';')[0].toLowerCase();if(!['audio/mpeg','audio/mp3','audio/wav','audio/x-wav','audio/webm','audio/ogg','audio/mp4','audio/aac','video/webm','video/mp4','video/quicktime','application/pdf'].includes(type))fail(400,'Supported formats: MP3, WAV, M4A, OGG, WebM, MP4, MOV and PDF.');if(type==='application/pdf'&&u.role!=='tutor')fail(400,'Submit an audio or video performance.');const id=crypto.randomUUID(),key=u.id+'/'+id;await env.MEDIA.put(key,await file.arrayBuffer(),{httpMetadata:{contentType:type}});try{await stmt(env,'INSERT INTO media VALUES(?,?,?,?,?,?,?)',id,u.id,key,text(file.name||'recording',180,true),type,file.size,Date.now()).run()}catch(e){await env.MEDIA.delete(key);throw e}return json({id,name:file.name,type,size:file.size},201)}
 if(path.startsWith('media/')&&(method==='GET'||method==='HEAD')){const id=path.slice(6),m=await first(env,`SELECT * FROM media m WHERE m.id=? AND (m.owner_id=? OR EXISTS(SELECT 1 FROM assignments a WHERE (a.tutor_id=? OR a.student_id=?) AND (a.demo_id=m.id OR a.sheet_id=m.id)) OR EXISTS(SELECT 1 FROM submissions s JOIN assignments a ON a.id=s.assignment_id WHERE (a.tutor_id=? OR a.student_id=?) AND s.media_id=m.id) OR EXISTS(SELECT 1 FROM reviews r JOIN submissions s ON s.id=r.submission_id JOIN assignments a ON a.id=s.assignment_id WHERE (a.tutor_id=? OR a.student_id=?) AND r.media_id=m.id))`,id,u.id,u.id,u.id,u.id,u.id,u.id,u.id);if(!m)fail(404,'Recording not found.');let range;const requested=req.headers.get('Range');if(requested){const match=/^bytes=(\d*)-(\d*)$/.exec(requested);if(!match||(!match[1]&&!match[2]))fail(416,'Invalid media range.');const offset=match[1]?Number(match[1]):Math.max(0,m.size-Number(match[2])),end=match[1]&&match[2]?Math.min(Number(match[2]),m.size-1):m.size-1;if(offset>end||offset>=m.size)fail(416,'Media range is outside the recording.');range={offset,length:end-offset+1};}const obj=await env.MEDIA.get(m.object_key,range?{range}:undefined);if(!obj)fail(404,'Recording unavailable.');const headers={'Content-Type':m.type,'Content-Length':String(obj.range?.length||obj.size),'Accept-Ranges':'bytes','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Content-Disposition':m.type==='application/pdf'?'attachment':'inline'};if(obj.range)headers['Content-Range']=`bytes ${obj.range.offset}-${obj.range.offset+obj.range.length-1}/${obj.size}`;return new Response(method==='HEAD'?null:obj.body,{status:obj.range?206:200,headers})}
 if(path==='assignments'&&method==='POST'){tutor(u);const b=await body(req);if(!await first(env,'SELECT student_id FROM students WHERE tutor_id=? AND student_id=?',u.id,b.studentId))fail(400,'Choose one of your enrolled students.');const id=crypto.randomUUID(),title=text(b.title,150,true),instructions=text(b.instructions,6000,true),demo=await ownMedia(env,u,b.demoId,'demo'),sheet=await ownMedia(env,u,b.sheetId,'sheet'),tempo=b.tempo?Number(b.tempo):null,due=b.due?text(b.due,10):null;if(tempo!==null&&(!Number.isInteger(tempo)||tempo<30||tempo>300))fail(400,'Tempo must be 30–300 BPM.');if(due&&!/^\d{4}-\d{2}-\d{2}$/.test(due))fail(400,'Choose a valid due date.');await stmt(env,'INSERT INTO assignments VALUES(?,?,?,?,?,?,?,?,?,?)',id,u.id,b.studentId,title,instructions,tempo,due,demo,sheet,Date.now()).run();return json({id},201)}
