 const seed=await first(env,'SELECT * FROM learning_seed WHERE user_id=?',u.id),totals=await first(env,'SELECT COALESCE(SUM(sessions),0) sessions,COALESCE(SUM(minutes),0) minutes,COALESCE(MAX(best),0) best FROM learning_events WHERE user_id=?',u.id);
